    private void BuildGlobalSettingsMenu(GuitarGameplaySnapshot snapshot)

    {

        if (globalSettingsScrollView == null)

            return;



        globalSettingsScrollView.Clear();

        globalSettingsMenuRows.Clear();



        bool inSubmenu = !string.IsNullOrEmpty(snapshot.activeGlobalSettingsCategory);

        globalSettingsTitleLabel.text = inSubmenu ? snapshot.activeGlobalSettingsCategory : "SETTINGS";

        globalSettingsHelpLabel.text = string.Empty;
        globalSettingsHelpLabel.style.display = DisplayStyle.None;



        VisualElement menuList = new VisualElement();

        menuList.style.width = Length.Percent(100f);

        menuList.style.maxWidth = 1280f;

        menuList.style.alignSelf = Align.Center;

        menuList.style.paddingTop = 8f;

        menuList.style.paddingBottom = 12f;

        globalSettingsScrollView.Add(menuList);



        if (!inSubmenu)

        {

            AddGlobalSettingsTopRow(menuList, 0, "Invert Strings", snapshot.selectedGlobalSettingsTopIndex == 0, snapshot.availableSongNames != null, snapshot.activeGlobalSettingsCategory, snapshot, snapshot.selectedGlobalSettingsTopIndex, snapshot.selectedGlobalSettingsItemIndex, snapshot.runtimeSettingsSections);

            AddGlobalSettingsTopRow(menuList, 1, "Render Mode", snapshot.selectedGlobalSettingsTopIndex == 1, snapshot.availableSongNames != null, snapshot.activeGlobalSettingsCategory, snapshot, snapshot.selectedGlobalSettingsTopIndex, snapshot.selectedGlobalSettingsItemIndex, snapshot.runtimeSettingsSections);

            AddGlobalSettingsTopRow(menuList, 2, "Songs Folder", snapshot.selectedGlobalSettingsTopIndex == 2, snapshot.availableSongNames != null, snapshot.activeGlobalSettingsCategory, snapshot, snapshot.selectedGlobalSettingsTopIndex, snapshot.selectedGlobalSettingsItemIndex, snapshot.runtimeSettingsSections);

            AddGlobalSettingsTopRow(menuList, 3, "Effects Folder", snapshot.selectedGlobalSettingsTopIndex == 3, snapshot.availableSongNames != null, snapshot.activeGlobalSettingsCategory, snapshot, snapshot.selectedGlobalSettingsTopIndex, snapshot.selectedGlobalSettingsItemIndex, snapshot.runtimeSettingsSections);

            AddGlobalSettingsTopCategoryRow(menuList, 4, "Audio", snapshot.selectedGlobalSettingsTopIndex == 4);

            AddGlobalSettingsTopCategoryRow(menuList, 5, "Gameplay", snapshot.selectedGlobalSettingsTopIndex == 5);

            AddGlobalSettingsTopCategoryRow(menuList, 6, "2D Tabs", snapshot.selectedGlobalSettingsTopIndex == 6);

            AddGlobalSettingsTopCategoryRow(menuList, 7, "Highway3D", snapshot.selectedGlobalSettingsTopIndex == 7);

            AddGlobalSettingsTopCategoryRow(menuList, 8, "Rhythm", snapshot.selectedGlobalSettingsTopIndex == 8);

            AddGlobalSettingsTopCategoryRow(menuList, 9, "Controls", snapshot.selectedGlobalSettingsTopIndex == 9);

            AddGlobalSettingsTopCategoryRow(menuList, 10, "Visuals", snapshot.selectedGlobalSettingsTopIndex == 10);

            AddGlobalSettingsTopCategoryRow(menuList, 11, "Multiplayer Visuals", snapshot.selectedGlobalSettingsTopIndex == 11);

            AddGlobalSettingsTopCategoryRow(menuList, 12, "Diagnostics", snapshot.selectedGlobalSettingsTopIndex == 12);

            AddGlobalSettingsTopCategoryRow(menuList, 13, "Reset Settings", snapshot.selectedGlobalSettingsTopIndex == 13, "DEFAULTS");

            return;

        }

        if (string.Equals(snapshot.activeGlobalSettingsCategory, "Audio", StringComparison.OrdinalIgnoreCase))
            AddGlobalSettingsAudioToneLabHint(menuList);



        List<RuntimeSettingSnapshot> items = GetGlobalSettingsMenuItems(snapshot);

        for (int i = 0; i < items.Count; i++)

        {

            RuntimeSettingSnapshot setting = items[i];

            AddGlobalSettingsSettingRow(menuList, setting, i, i == snapshot.selectedGlobalSettingsItemIndex);

        }

    }



    private List<RuntimeSettingSnapshot> GetGlobalSettingsMenuItems(GuitarGameplaySnapshot snapshot)

    {

        if (snapshot.runtimeSettingsSections == null || string.IsNullOrEmpty(snapshot.activeGlobalSettingsCategory))

            return new List<RuntimeSettingSnapshot>();



        return snapshot.runtimeSettingsSections

            .Where(section => string.Equals(CategorizeGlobalSettingsSection(section), snapshot.activeGlobalSettingsCategory, StringComparison.OrdinalIgnoreCase))

            .SelectMany(section => section.settings ?? new List<RuntimeSettingSnapshot>())

            .Where(setting => setting != null && !string.Equals(setting.id, "core.invertStrings", StringComparison.OrdinalIgnoreCase) && !string.Equals(setting.id, "render.mode", StringComparison.OrdinalIgnoreCase))

            .ToList();

    }



    private void AddGlobalSettingsTopRow(VisualElement parent, int index, string title, bool isSelected, bool _, string __, GuitarGameplaySnapshot snapshot, int ___, int ____, List<RuntimeSettingSectionSnapshot> _____)

    {

        string value;
        bool showArrows;
        Action onLeft;
        Action onRight;

        if (index == 0)
        {
            value = ResolveGlobalSettingValue(snapshot.runtimeSettingsSections, "core.invertStrings", string.Empty);
            value = string.Equals(value, "true", StringComparison.OrdinalIgnoreCase) ? "ON" : "OFF";
            showArrows = true;
            onLeft = () => owner?.AdjustGlobalSettingsTopValueFromUi(index, -1);
            onRight = () => owner?.AdjustGlobalSettingsTopValueFromUi(index, 1);
        }
        else if (index == 1)
        {
            value = ResolveGlobalSettingValue(snapshot.runtimeSettingsSections, "render.mode", string.Empty);
            showArrows = true;
            onLeft = () => owner?.AdjustGlobalSettingsTopValueFromUi(index, -1);
            onRight = () => owner?.AdjustGlobalSettingsTopValueFromUi(index, 1);
        }
        else if (index == 2)
        {
            value = snapshot.songsFolderMenuValueLabel ?? "DEFAULT";
            showArrows = false;
            onLeft = null;
            onRight = null;
        }
        else
        {
            value = snapshot.effectsFolderMenuValueLabel ?? "DEFAULT";
            showArrows = false;
            onLeft = null;
            onRight = null;
        }

        GlobalSettingsMenuRow row = CreateGlobalSettingsMenuRow(title, value, isSelected, showArrows: showArrows, onHover: () => owner?.HoverGlobalSettingsTopSelectionFromUi(index), onActivate: () => owner?.ActivateGlobalSettingsTopSelectionFromUi(index), onLeft: onLeft, onRight: onRight);

        parent.Add(row.row);

        globalSettingsMenuRows.Add(row);

    }



    private void AddGlobalSettingsTopCategoryRow(VisualElement parent, int index, string title, bool isSelected, string value = "ENTER")

    {

        GlobalSettingsMenuRow row = CreateGlobalSettingsMenuRow(title, value, isSelected, showArrows: false, onHover: () => owner?.HoverGlobalSettingsTopSelectionFromUi(index), onActivate: () => owner?.ActivateGlobalSettingsTopSelectionFromUi(index), onLeft: null, onRight: null);

        parent.Add(row.row);

        globalSettingsMenuRows.Add(row);

    }



    private void AddGlobalSettingsSettingRow(VisualElement parent, RuntimeSettingSnapshot setting, int index, bool isSelected)

    {

        if (setting == null)

            return;



        string value = FormatGlobalSettingsValue(setting);
        bool adjustable = !string.Equals(setting.valueType, "binding", StringComparison.OrdinalIgnoreCase) &&
                          !string.Equals(setting.valueType, "action", StringComparison.OrdinalIgnoreCase);
        bool showAudioSelectorHint = isSelected && IsAudioDevicePopupSetting(setting);
        string metaText = showAudioSelectorHint ? "ENTER opens list selector" : GetGlobalSettingMetaText(setting);
        GlobalSettingsMenuRow row = CreateGlobalSettingsMenuRow(setting.label, value, isSelected, showArrows: adjustable, onHover: () => owner?.HoverGlobalSettingsItemSelectionFromUi(index), onActivate: () => owner?.ActivateGlobalSettingsItemSelectionFromUi(index), onLeft: adjustable ? (Action)(() => owner?.AdjustGlobalSettingsItemValueFromUi(index, -1)) : null, onRight: adjustable ? (Action)(() => owner?.AdjustGlobalSettingsItemValueFromUi(index, 1)) : null, metaText: metaText, metaAlignRight: showAudioSelectorHint, metaColor: showAudioSelectorHint ? new Color(0.74f, 0.88f, 0.98f, 0.92f) : new Color(0.56f, 0.63f, 0.70f, 0.96f));

        parent.Add(row.row);

        globalSettingsMenuRows.Add(row);

    }



    private GlobalSettingsMenuRow CreateGlobalSettingsMenuRow(string title, string value, bool isSelected, bool showArrows, Action onHover, Action onActivate, Action onLeft, Action onRight, string metaText = null, bool metaAlignRight = false, Color? metaColor = null)

    {

        VisualElement row = new VisualElement();

        row.style.flexDirection = FlexDirection.Column;

        row.style.width = Length.Percent(100f);

        row.style.marginBottom = 18f;

        row.style.paddingLeft = 12f;

        row.style.paddingRight = 12f;

        row.style.paddingTop = 8f;

        row.style.paddingBottom = 8f;



        VisualElement topLine = new VisualElement();

        topLine.style.flexDirection = FlexDirection.Row;

        topLine.style.alignItems = Align.Center;

        topLine.style.justifyContent = Justify.SpaceBetween;

        topLine.style.width = Length.Percent(100f);



        Button mainButton = new Button(() => onActivate?.Invoke());

        mainButton.text = title;

        mainButton.focusable = false;

        mainButton.style.flexGrow = 1f;

        mainButton.style.height = 84f;

        mainButton.style.backgroundColor = new Color(0f, 0f, 0f, 0f);

        mainButton.style.color = isSelected ? Color.white : new Color(0.86f, 0.89f, 0.92f, 1f);

        mainButton.style.fontSize = 46f;

        mainButton.style.unityFontDefinition = modernUiFontDefinition;

        mainButton.style.unityFontStyleAndWeight = FontStyle.Bold;

        mainButton.style.unityTextAlign = TextAnchor.MiddleLeft;

        mainButton.style.paddingLeft = 0f;

        mainButton.style.paddingRight = 16f;

        mainButton.style.borderTopWidth = 0f;

        mainButton.style.borderRightWidth = 0f;

        mainButton.style.borderBottomWidth = 0f;

        mainButton.style.borderLeftWidth = 0f;

        mainButton.style.backgroundImage = StyleKeyword.None;

        mainButton.RegisterCallback<MouseEnterEvent>(_ => onHover?.Invoke());

        AttachWheelScrolling(mainButton, globalSettingsScrollView);



        VisualElement valueWrap = new VisualElement();

        valueWrap.style.flexDirection = FlexDirection.Row;

        valueWrap.style.alignItems = Align.Center;

        valueWrap.style.justifyContent = Justify.FlexEnd;

        valueWrap.style.minWidth = 360f;



        Button leftButton = null;

        Button rightButton = null;

        if (showArrows)

        {

            leftButton = CreateGlobalSettingsArrowButton("\u2039", onLeft);

            rightButton = CreateGlobalSettingsArrowButton("\u203A", onRight);

            valueWrap.Add(leftButton);

        }



        Label valueLabel = CreateLabel(value, 40f, isSelected ? LibraryPrimaryColor : new Color(0.72f, 0.77f, 0.82f, 1f), true, TextAnchor.MiddleCenter, useTitleFont: false);

        valueLabel.style.unityFontDefinition = modernUiFontDefinition;

        valueLabel.style.minWidth = 180f;

        valueLabel.style.unityTextAlign = TextAnchor.MiddleCenter;

        valueWrap.Add(valueLabel);



        if (showArrows)

        {

            valueWrap.Add(rightButton);

        }

        valueWrap.RegisterCallback<PointerDownEvent>(evt =>
        {
            if (evt.button != 0)
                return;

            if (evt.target is VisualElement element)
            {
                if ((leftButton != null && (element == leftButton || leftButton.Contains(element))) ||
                    (rightButton != null && (element == rightButton || rightButton.Contains(element))))
                    return;
            }

            onActivate?.Invoke();
            evt.StopPropagation();
        });



        topLine.Add(mainButton);

        topLine.Add(valueWrap);

        row.Add(topLine);



        Label metaLabel = null;

        if (!string.IsNullOrWhiteSpace(metaText))

        {

            metaLabel = CreateLabel(metaText, 20f, metaColor ?? new Color(0.56f, 0.63f, 0.70f, 0.96f), false, metaAlignRight ? TextAnchor.MiddleRight : TextAnchor.MiddleLeft, useTitleFont: false);

            metaLabel.style.unityFontDefinition = modernUiFontDefinition;

            metaLabel.style.whiteSpace = WhiteSpace.Normal;

            metaLabel.style.marginTop = 4f;

            metaLabel.style.alignSelf = metaAlignRight ? Align.FlexEnd : Align.FlexStart;

            metaLabel.style.unityTextAlign = metaAlignRight ? TextAnchor.MiddleRight : TextAnchor.MiddleLeft;

            row.Add(metaLabel);

        }



        ConfigureGlobalSettingsMenuRowHover(row, mainButton, valueLabel, isSelected, onHover);



        return new GlobalSettingsMenuRow

        {

            row = row,

            titleLabel = null,

            valueLabel = valueLabel,

            leftButton = leftButton,

            rightButton = rightButton,

            metaLabel = metaLabel

        };

    }



    private static string ResolveGlobalSettingValue(List<RuntimeSettingSectionSnapshot> sections, string settingId, string fallback)

    {

        if (sections == null || string.IsNullOrEmpty(settingId))

            return fallback;



        foreach (RuntimeSettingSectionSnapshot section in sections)

        {

            if (section?.settings == null)

                continue;



            RuntimeSettingSnapshot match = section.settings.FirstOrDefault(setting => setting != null && string.Equals(setting.id, settingId, StringComparison.OrdinalIgnoreCase));

            if (match != null)

                return match.value ?? fallback;

        }



        return fallback;

    }



    private static string FormatGlobalSettingsValue(RuntimeSettingSnapshot setting)

    {

        if (setting == null)

            return string.Empty;



        if (string.Equals(setting.valueType, "bool", StringComparison.OrdinalIgnoreCase))

            return string.Equals(setting.value, "true", StringComparison.OrdinalIgnoreCase) ? "ON" : "OFF";

        if (string.Equals(setting.valueType, "binding", StringComparison.OrdinalIgnoreCase))

            return FormatBindingDisplayValue(setting.value);

        if (!string.IsNullOrWhiteSpace(setting.id) &&
            (string.Equals(setting.id, "audio.globalInputGain", StringComparison.OrdinalIgnoreCase) ||
             string.Equals(setting.id, "audio.globalOutputGain", StringComparison.OrdinalIgnoreCase)) &&
            float.TryParse(setting.value, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out float gainDb))
        {
            return $"{gainDb:0.#} dB";
        }

        if (!string.IsNullOrWhiteSpace(setting.id) &&
            (string.Equals(setting.id, "audio.songVolume", StringComparison.OrdinalIgnoreCase) ||
             string.Equals(setting.id, "audio.guitarVolume", StringComparison.OrdinalIgnoreCase)) &&
            float.TryParse(setting.value, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out float percent))
        {
            return $"{percent:0}%";
        }



        return setting.value ?? string.Empty;

    }



    private static string GetGlobalSettingMetaText(RuntimeSettingSnapshot setting)

    {

        if (setting == null || string.IsNullOrWhiteSpace(setting.tooltip))

            return string.Empty;



        return !string.IsNullOrWhiteSpace(setting.id) && setting.id.StartsWith("audio.", StringComparison.OrdinalIgnoreCase)

            ? string.Empty

            : setting.tooltip;

    }

    private static bool IsAudioDevicePopupSetting(RuntimeSettingSnapshot setting)
    {
        if (setting == null || string.IsNullOrWhiteSpace(setting.id))
            return false;

        return string.Equals(setting.id, "audio.inputDevice", StringComparison.OrdinalIgnoreCase) ||
               string.Equals(setting.id, "audio.outputDevice", StringComparison.OrdinalIgnoreCase);
    }



